insert into public.hodnotenia (majster_id, poradie, text, autor, praca, mesiac, hviezdy) values
  (0, 1, '„Po maliaroch bol byt ako nový. Prišla presne a mala vlastné prostriedky.“', 'Michal, Bratislava', 'upratovanie po rekonštrukcii', 'október 2026', 5),
  (0, 2, '„Okná bez šmúh, aj rámy a parapety.“', 'Michal, Bratislava – Ružinov', 'umývanie okien', 'september 2026', 5),
  (0, 3, '„Spoľahlivo každý druhý piatok, kľúče v dobrých rukách.“', 'Katarína, Bratislava – Rača', 'pravidelné upratovanie', 'august 2026', 5),
  (1, 1, '„Príchod presne v dohodnutý čas a cena sedela s ponukou do eura.“', 'Ondrej, Bratislava – Staré Mesto', 'nové zásuvky v kuchyni', 'september 2026', 5),
  (1, 2, '„Revízna správa hotová ešte v ten deň, presne pre banku, ako sme potrebovali.“', 'Alena, Bratislava – Nové Mesto', 'revízia bytu', 'august 2026', 5),
  (1, 3, '„Svetlá v obývačke vyzerajú skvele a kábel nikde nevidno.“', 'Peter, Bratislava – Dúbravka', 'LED osvetlenie', 'júl 2026', 4),
  (2, 1, '„Pekne osadené WC, žiadne zbytočné vŕtanie.“', 'Lucia, Bratislava – Ružinov', 'montáž WC', 'august 2026', 5),
  (2, 2, '„Ochota a dobrá rada aj pri výbere batérie.“', 'Tomáš, Bratislava – Rača', 'výmena batérie', 'júl 2026', 5),
  (2, 3, '„Bojler vymenený za pár hodín a starý aj odvezený.“', 'Zuzana, Bratislava – Karlova Ves', 'výmena bojlera', 'jún 2026', 5),
  (3, 1, '„Termín dodržaný, byt hotový ešte pred sťahovaním.“', 'Marek, Bratislava – Nové Mesto', 'maľovanie pred sťahovaním', 'júl 2026', 5),
  (3, 2, '„Bez prachu a bez fľakov, nábytok bol pekne zakrytý.“', 'Eva, Bratislava – Dúbravka', 'maľovanie bytu', 'jún 2026', 5),
  (3, 3, '„Steny sú konečne rovné, stierka bola dobrá voľba.“', 'Juraj, Bratislava – Petržalka', 'stierka a maľba', 'október 2026', 4),
  (4, 1, '„Parkety po brúsení ako nové a prachu minimum.“', 'Jana, Bratislava – Rača', 'brúsenie parkiet', 'jún 2026', 5),
  (4, 2, '„Vinyl za dva dni, prechody presne na milimeter.“', 'Michal, Bratislava – Karlova Ves', 'vinyl v byte', 'október 2026', 5),
  (4, 3, '„Podklad poctivo vyrovnaný, nič nevŕzga.“', 'Katarína, Senec', 'laminát', 'september 2026', 5),
  (5, 1, '„Skriňa do šikmín využila každý centimeter.“', 'Ondrej, Bratislava – Dúbravka', 'vstavaná skriňa', 'október 2026', 5),
  (5, 2, '„Schody krásne, pevné a nevŕzgajú.“', 'Alena, Bratislava – Petržalka', 'drevené schody', 'september 2026', 5),
  (5, 3, '„Starý príborník po renovácii ako nový.“', 'Peter, Pezinok', 'renovácia nábytku', 'august 2026', 5),
  (6, 1, '„Vymenil rozvádzač za jeden deň, všetko vysvetlil a po sebe upratal.“', 'Jana, Hlohovec', 'výmena rozvádzača', 'október 2026', 5),
  (6, 2, '„Revízna správa hotová ešte v ten deň, presne pre banku, ako sme potrebovali.“', 'Lucia, Šamorín', 'revízia bytu', 'september 2026', 5),
  (6, 3, '„Svetlá v obývačke vyzerajú skvele a kábel nikde nevidno.“', 'Tomáš, Skalica', 'LED osvetlenie', 'august 2026', 5),
  (7, 1, '„Škáry ako podľa pravítka a cena sedela s ponukou do eura.“', 'Katarína, Šamorín', 'obklad kúpeľne', 'október 2026', 5),
  (7, 2, '„Všetko čisto odovzdané a odpad odvezený.“', 'Marek, Senica', 'kúpeľňa na kľúč', 'august 2026', 5),
  (7, 3, '„Sprchový kút bez vaničky vyzerá ako z katalógu.“', 'Juraj, Hlohovec', 'sprchový kút', 'jún 2026', 5),
  (8, 1, '„Plot ostrihaný do roviny a všetko pozametané.“', 'Jana, Skalica', 'strihanie plota', 'júl 2026', 5),
  (8, 2, '„Kosenie každé dva týždne bez pripomínania.“', 'Michal, Piešťany', 'pravidelné kosenie', 'jún 2026', 5),
  (8, 3, '„Stromy po reze krásne zarodili.“', 'Katarína, Galanta', 'rez stromov', 'október 2026', 4),
  (9, 1, '„Skrine rozobraté aj zložené, nemuseli sme hľadať náradie.“', 'Ondrej, Trnava', 'sťahovanie s demontážou', 'jún 2026', 5),
  (9, 2, '„Pivnica vypratá a všetko odvezené na zberný dvor.“', 'Alena, Hlohovec', 'vypratanie pivnice', 'október 2026', 5),
  (9, 3, '„Dohodnutá cena platila, aj keď to trvalo dlhšie.“', 'Peter, Sereď', 'sťahovanie kancelárie', 'september 2026', 4),
  (10, 1, '„Harmonogram dodržaný na deň presne.“', 'Lucia, Piešťany', 'rekonštrukcia bytu', 'október 2026', 5),
  (10, 2, '„Podhľad bez jedinej trhliny ani po roku.“', 'Tomáš, Galanta', 'sadrokartón', 'september 2026', 5),
  (10, 3, '„Jadro vybúrané a nové priečky stáli do týždňa.“', 'Zuzana, Dunajská Streda', 'rekonštrukcia jadra', 'august 2026', 5),
  (11, 1, '„Ochota a dobrá rada aj pri výbere batérie.“', 'Marek, Považská Bystrica', 'výmena batérie', 'september 2026', 5),
  (11, 2, '„Bojler vymenený za pár hodín a starý aj odvezený.“', 'Eva, Púchov', 'výmena bojlera', 'august 2026', 5),
  (11, 3, '„Keď nám večer tieklo pod drezom, pomoc prišla ešte v ten deň.“', 'Juraj, Partizánske', 'havarijná oprava', 'júl 2026', 5),
  (12, 1, '„Príchod v dohodnutý čas a správu pre poisťovňu sme mali hneď.“', 'Jana, Dubnica nad Váhom', 'kontrola komína', 'august 2026', 5),
  (12, 2, '„Na kamere bolo jasne vidno prasklinu aj navrhnuté riešenie.“', 'Michal, Prievidza', 'kamerová prehliadka', 'júl 2026', 5),
  (12, 3, '„Čisto odvedená práca, v obývačke ani smietka.“', 'Katarína, Bánovce nad Bebravou', 'čistenie krbu', 'jún 2026', 5),
  (13, 1, '„Okná bez šmúh, aj rámy a parapety.“', 'Ondrej, Púchov', 'umývanie okien', 'júl 2026', 5),
  (13, 2, '„Spoľahlivo každý druhý piatok, kľúče v dobrých rukách.“', 'Alena, Partizánske', 'pravidelné upratovanie', 'jún 2026', 5),
  (13, 3, '„Sedačka po tepovaní ako nová, fľaky po deťoch sú preč.“', 'Peter, Myjava', 'tepovanie sedačky', 'október 2026', 5),
  (14, 1, '„Strecha hotová v termíne a okolie domu upratané.“', 'Lucia, Prievidza', 'nová krytina', 'jún 2026', 5),
  (14, 2, '„Strešné okno osadené bez jedinej kvapky.“', 'Tomáš, Bánovce nad Bebravou', 'strešné okno', 'október 2026', 5),
